import{_ as n,o as t,c as s,a0 as o}from"./chunks/framework.DVUHX04-.js";const p=JSON.parse('{"title":"Usage events are counted once, keyed by the full session line","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0009-usage-events-counted-once-per-distinct-line.md","filePath":"adr/0009-usage-events-counted-once-per-distinct-line.md","lastUpdated":1789465415000}'),a={name:"adr/0009-usage-events-counted-once-per-distinct-line.md"};function i(r,e,d,c,l,u){return t(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="usage-events-are-counted-once-keyed-by-the-full-session-line" tabindex="-1">Usage events are counted once, keyed by the full session line <a class="header-anchor" href="#usage-events-are-counted-once-keyed-by-the-full-session-line" aria-label="Permalink to &quot;Usage events are counted once, keyed by the full session line&quot;">​</a></h1><p>Forked and cloned sessions copy their ancestor&#39;s entry lines byte-identical into the new file. A scan that sums every file would count the shared history once per fork. Each usage event is therefore counted once per distinct line: the scan keeps the set of full JSONL lines that carried a usage event and counts a line only the first time it appears.</p><h2 id="considered-options" tabindex="-1">Considered options <a class="header-anchor" href="#considered-options" aria-label="Permalink to &quot;Considered options&quot;">​</a></h2><ul><li><strong>Entry <code>id</code>.</strong> Entry ids are 8 hex chars and random; they collide across unrelated sessions, so an id alone cannot tell a copy from a collision.</li><li><strong>The <code>parentSession</code> header.</strong> It names one parent, not the whole copied chain, and older forks may lack it.</li><li><strong><code>(session id, entry id)</code> pairs.</strong> A fork is a different session, so the pair does not merge the copy with the original.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Counting depends on pi writing fork copies byte-identical. If that ever changes, the dedupe silently overcounts instead of undercounting; a test on a fork fixture guards the invariant.</li><li>Two truly distinct events with identical bytes would merge. In practice an event line carries a random entry id, so identical bytes mean a copy.</li></ul>',6)])])}const f=n(a,[["render",i]]);export{p as __pageData,f as default};
